import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])
    m = int(data[1])

    if n == 0 or m == 0:
        print(-1)
        return

    edges = []
    idx = 2
    for i in range(m):
        u = int(data[idx])
        v = int(data[idx + 1])
        w = int(data[idx + 2])
        idx += 3
        edges.append((w, u - 1, v - 1))

    edges.sort()

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx = find(x)
        ry = find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_weight = 0
    edges_used = 0

    for w, u, v in edges:
        if union(u, v):
            mst_weight += w
            edges_used += 1
            if edges_used == n - 1:
                break

    print(mst_weight)

if __name__ == "__main__":
    main()
